}
pub inline fn INCREF(x: anytype) @TypeOf((((x & ~N_BTMASK) << N_TSHIFT) | (IMAGE_SYM_DTYPE_POINTER << N_BTSHFT)) | (x & N_BTMASK)) {
    _ = &x;
    return (((x & ~N_BTMASK) << N_TSHIFT) | (IMAGE_SYM_DTYPE_POINTER << N_BTSHFT)) | (x & N_BTMASK);
}
pub inline fn DECREF(x: anytype) @TypeOf(((x >> N_TSHIFT) & ~N_BTMASK) | (x & N_BTMASK)) {
    _ = &x;
